[{"category":"section","location":"api/#Chemistry","page":"API","text":"","title":"Chemistry"},{"category":"section","location":"api/#Reactions","page":"API","text":"","title":"Reactions"},{"category":"section","location":"api/#Network","page":"API","text":"","title":"Network"},{"category":"section","location":"api/#I/O","page":"API","text":"","title":"I/O"},{"category":"section","location":"api/#Constants","page":"API","text":"","title":"Constants"},{"category":"section","location":"api/#Chemistry-2","page":"API","text":"","title":"Chemistry"},{"category":"method","location":"api/#JUCLCHEM._get_factor_1-NTuple{4, Real}","page":"API","text":"_get_factor_1(μ, ν, E_H2, T_dust)\n\nThe first term in equation 15 from Cazaux & Tielens, 2002.\n\n\n\n\n\n","title":"JUCLCHEM._get_factor_1"},{"category":"method","location":"api/#JUCLCHEM._get_factor_2-NTuple{4, Real}","page":"API","text":"_get_factor_2(E_HC, E_S, E_HP, T_dust)\n\nEquation 17 from Cazaux & Tielens, 2002.\n\n\n\n\n\n","title":"JUCLCHEM._get_factor_2"},{"category":"method","location":"api/#JUCLCHEM._get_ϵ-NTuple{5, Real}","page":"API","text":"_get_ϵ(ν, E_HC, E_S, E_HP, T_dust)\n\nEquation 16 from Cazaux & Tielens, 2002.\n\n\n\n\n\n","title":"JUCLCHEM._get_ϵ"},{"category":"method","location":"api/#JUCLCHEM.get_arrhenius_probability-Tuple{Real, Real}","page":"API","text":"get_arrhenius_probability(E_reac, temperature)\n\nP = e^-ET\n\n\n\n\n\n","title":"JUCLCHEM.get_arrhenius_probability"},{"category":"method","location":"api/#JUCLCHEM.get_eley_rideal_rate_constant-NTuple{5, Real}","page":"API","text":"get_eley_rideal_rate_constant(freezeout_rate, γ, μ_ij, T_dust)\n\nEquation 25 from Vermarien et al, 2025.\n\n\n\n\n\n","title":"JUCLCHEM.get_eley_rideal_rate_constant"},{"category":"function","location":"api/#JUCLCHEM.get_reaction_probability","page":"API","text":"get_reaction_probability(E_reac, μ_ij, T_dust, barrier_width=1.4)\n\nGet the total reaction probability (including tunneling).\n\nMaximum of get_arrhenius_probability and get_tunneling_probability\n\n\n\n\n\n","title":"JUCLCHEM.get_reaction_probability"},{"category":"method","location":"api/#JUCLCHEM.get_sticking_coefficient_Hollenbach_McKee-Tuple{Real, Real}","page":"API","text":"get_sticking_coefficient_Hollenbach_McKee(T_gas, T_dust)\n\nEquation 3.7 from Hollenbach & McKee 1979.\n\n\n\n\n\n","title":"JUCLCHEM.get_sticking_coefficient_Hollenbach_McKee"},{"category":"method","location":"api/#JUCLCHEM.get_thermal_desorption_rate_constant-Tuple{Real, Real, Real}","page":"API","text":"get_thermal_desorption_rate_constant(E_bind, ν_des, T_dust)\n\nThe thermal desorption rate constant,\n\nnu_mathrmdese^-E_mathrmbindT_mathrmdust\n\n\n\n\n\n","title":"JUCLCHEM.get_thermal_desorption_rate_constant"},{"category":"method","location":"api/#JUCLCHEM.get_thermal_diffusion_rate_constant-Tuple{Real, Real, Real}","page":"API","text":"get_thermal_diffusion_rate_constant(E_diff, ν_diff, T_dust)\n\nThe thermal diffusion rate constant,\n\nnu_mathrmdiffe^-E_mathrmdiffT_mathrmdust\n\n\n\n\n\n","title":"JUCLCHEM.get_thermal_diffusion_rate_constant"},{"category":"method","location":"api/#JUCLCHEM.get_thermal_velocity-Tuple{Real, Real}","page":"API","text":"get_thermal_velocity(mass, T)\n\nv_mathrmth=sqrtfrac8k_mathrmBTπm\n\n\n\n\n\n","title":"JUCLCHEM.get_thermal_velocity"},{"category":"method","location":"api/#JUCLCHEM.get_tunneling_probability-Tuple{Real, Real, Real}","page":"API","text":"get_tunneling_probability(E_reac, μ_ij, barrier_width)\n\nP = e^frac-2ahbarsqrt2mu_ijE_mathrmreac\n\n\n\n\n\n","title":"JUCLCHEM.get_tunneling_probability"},{"category":"method","location":"api/#JUCLCHEM.get_ν_HH-Tuple{Real, Real}","page":"API","text":"get_ν_HH(E_bind, mass)\n\nnu_mathrmHH=sqrtfrac2*SURFACE_SITE_DENSITY*E_mathrmbindπ^2m\n\n\n\n\n\n","title":"JUCLCHEM.get_ν_HH"},{"category":"method","location":"api/#JUCLCHEM.get_crp_photo_rate_constant-NTuple{6, Real}","page":"API","text":"get_crp_photo_rate_constant(α, β, γ, ω_dust, ζ, T_gas)\n\nGet the rate constant of a CRPHOTO reaction.\n\nk = α * γ  (1-ω_mathrmdust) * ζ * (T_mathrmgas300)^beta\n\n\n\n\n\n","title":"JUCLCHEM.get_crp_photo_rate_constant"},{"category":"method","location":"api/#JUCLCHEM.get_ionopol1_rate_constant-NTuple{4, Real}","page":"API","text":"Equation 1 from Wakelam et al, 2024.\n\n\n\n\n\n","title":"JUCLCHEM.get_ionopol1_rate_constant"},{"category":"method","location":"api/#JUCLCHEM.get_ionopol2_rate_constant-NTuple{4, Real}","page":"API","text":"Equation 2 from Wakelam et al, 2024.\n\n\n\n\n\n","title":"JUCLCHEM.get_ionopol2_rate_constant"},{"category":"method","location":"api/#JUCLCHEM.get_photo_rate_constant-NTuple{4, Real}","page":"API","text":"get_photo_rate_constant(α, γ, radfield, A_V)\n\nGet the rate constant of a photo-reaction.\n\nk = alpha * F_mathrmUV e^-gamma * A_mathrmV  17\n\n\n\n\n\n","title":"JUCLCHEM.get_photo_rate_constant"},{"category":"method","location":"api/#JUCLCHEM.get_twobody_rate_constant-NTuple{4, Real}","page":"API","text":"get_twobody_rate_constant(α, β, γ, T_gas)\n\nGet the rate constant of a gas-phase twobody reaction, using the Arrhenius-Kooij equation.\n\nk = alpha (T_mathrmgas300)^beta e^-gammaT_mathrmgas\n\n\n\n\n\n","title":"JUCLCHEM.get_twobody_rate_constant"},{"category":"constant","location":"api/#JUCLCHEM.REACTION_COLUMN_TYPES","page":"API","text":"Mapping from the column name to the column data-type.\n\n\n\n\n\n","title":"JUCLCHEM.REACTION_COLUMN_TYPES"},{"category":"constant","location":"api/#JUCLCHEM.SPECIES_COLUMN_TYPES","page":"API","text":"Mapping from the column name to the column data type.\n\n\n\n\n\n","title":"JUCLCHEM.SPECIES_COLUMN_TYPES"},{"category":"method","location":"api/#JUCLCHEM.initialize_reaction-Tuple{CSV.Row}","page":"API","text":"initialize_reaction(row)\n\nInitialize a reaction from a row of a CSV file.\n\n\n\n\n\n","title":"JUCLCHEM.initialize_reaction"},{"category":"method","location":"api/#JUCLCHEM.initialize_species-Tuple{CSV.Row}","page":"API","text":"initialize_species(row)\n\nInitialize a species from a row of a CSV file.\n\n\n\n\n\n","title":"JUCLCHEM.initialize_species"},{"category":"method","location":"api/#JUCLCHEM.read_reaction_file-Tuple{AbstractString}","page":"API","text":"read_reaction_file(file)\n\nRead a list of UCLCHEM reactions.\n\n\n\n\n\n","title":"JUCLCHEM.read_reaction_file"},{"category":"method","location":"api/#JUCLCHEM.read_species_file-Tuple{AbstractString}","page":"API","text":"read_species_file(file)\n\nRead a list of UCLCHEM species.\n\n\n\n\n\n","title":"JUCLCHEM.read_species_file"},{"category":"constant","location":"api/#JUCLCHEM.ELEMENTS","page":"API","text":"Elements in the network\n\n\n\n\n\n","title":"JUCLCHEM.ELEMENTS"},{"category":"constant","location":"api/#JUCLCHEM.GAS_DUST_MASS_DENSITY_RATIO","page":"API","text":"m_mathrmgasm_mathrmdust\n\n\n\n\n\n","title":"JUCLCHEM.GAS_DUST_MASS_DENSITY_RATIO"},{"category":"constant","location":"api/#JUCLCHEM.GAS_DUST_NUMBER_DENSITY_RATIO","page":"API","text":"N_mathrmgasN_mathrmdust\n\nNote that this is defined as the reciprocal as it is in UCLCHEM.\n\n\n\n\n\n","title":"JUCLCHEM.GAS_DUST_NUMBER_DENSITY_RATIO"},{"category":"constant","location":"api/#JUCLCHEM.GRAIN_AREA","page":"API","text":"Area of a single grain in m^2.\n\n\n\n\n\n","title":"JUCLCHEM.GRAIN_AREA"},{"category":"constant","location":"api/#JUCLCHEM.GRAIN_DENSITY","page":"API","text":"Grain density in kg m^-3\n\n\n\n\n\n","title":"JUCLCHEM.GRAIN_DENSITY"},{"category":"constant","location":"api/#JUCLCHEM.GRAIN_MASS","page":"API","text":"Mass of a single grain in kg.\n\n\n\n\n\n","title":"JUCLCHEM.GRAIN_MASS"},{"category":"constant","location":"api/#JUCLCHEM.GRAIN_RADIUS","page":"API","text":"Grain radius in m\n\n\n\n\n\n","title":"JUCLCHEM.GRAIN_RADIUS"},{"category":"constant","location":"api/#JUCLCHEM.GRAIN_SURFACE_SITE_DENSITY","page":"API","text":"Number of sites on grain surface (m^-1)\n\n\n\n\n\n","title":"JUCLCHEM.GRAIN_SURFACE_SITE_DENSITY"},{"category":"constant","location":"api/#JUCLCHEM.GRAIN_VOLUME","page":"API","text":"Volume of a single grain in kg.\n\n\n\n\n\n","title":"JUCLCHEM.GRAIN_VOLUME"},{"category":"constant","location":"api/#JUCLCHEM.HABING_PER_DRAINE","page":"API","text":"Conversion between Habing and Draine\n\n\n\n\n\n","title":"JUCLCHEM.HABING_PER_DRAINE"},{"category":"constant","location":"api/#JUCLCHEM.MIN_ABUNDANCE","page":"API","text":"Minimum abundance.\n\n\n\n\n\n","title":"JUCLCHEM.MIN_ABUNDANCE"},{"category":"constant","location":"api/#JUCLCHEM.NUM_SITES_PER_GRAIN","page":"API","text":"Number of sites on a single grain.\n\n\n\n\n\n","title":"JUCLCHEM.NUM_SITES_PER_GRAIN"},{"category":"constant","location":"api/#JUCLCHEM.SECONDS_PER_YEAR","page":"API","text":"Number of seconds in one year.\n\n\n\n\n\n","title":"JUCLCHEM.SECONDS_PER_YEAR"},{"category":"constant","location":"api/#JUCLCHEM.ζ_0","page":"API","text":"Default Cosmic Ray Ionization Rate (s^-1)\n\n\n\n\n\n","title":"JUCLCHEM.ζ_0"},{"category":"method","location":"api/#JUCLCHEM.construct_elements_per_species_matrix-Tuple{AbstractVector{AbstractDict{AbstractString, Int64}}, AbstractVector{AbstractString}}","page":"API","text":"construct_elements_per_species_matrix(constituent_dicts, elements)\n\n\n\n\n\n","title":"JUCLCHEM.construct_elements_per_species_matrix"},{"category":"function","location":"api/#JUCLCHEM.get_freezeout_rate_constant","page":"API","text":"get_freezeout_rate_constant(α, β, mass, T_gas, freeze_factor=1)\n\nalpha(1+beta*1671e-4(r_mathrmgrainT_mathrmgas)*freeze_factor*v_mathrmth*GRAIN_CROSSSECTION_PER_H\n\n\n\n\n\n","title":"JUCLCHEM.get_freezeout_rate_constant"},{"category":"method","location":"api/#JUCLCHEM.get_number_of_monolayers-Tuple{Real}","page":"API","text":"get_number_of_monolayers(abundance)\n\nCalculated by N(N_mathrmsites-per-grain(N_mathrmdustN_mathrmgas)\n\n\n\n\n\n","title":"JUCLCHEM.get_number_of_monolayers"},{"category":"method","location":"api/#JUCLCHEM.get_sticking_coefficient-Tuple{Real, Real, Real}","page":"API","text":"get_sticking_coefficient(S_0, T_critical, T_gas)\n\nSticking coefficient for freeze out taken from Chaabouni et al. 2012 A&A 538 Equation 1\n\nS_T = S_0(1+beta T_mathrmgasT_mathrmcrit)((1+T_mathrmgasT_mathrmcrit)^beta)\n\n\n\n\n\n","title":"JUCLCHEM.get_sticking_coefficient"},{"category":"method","location":"api/#JUCLCHEM.get_total_elemental_abuncance-Tuple{AbstractVector{Real}, AbstractMatrix{Int64}}","page":"API","text":"get_total_elemental_abuncance(abundances, elements_per_species)\n\n\n\n\n\n","title":"JUCLCHEM.get_total_elemental_abuncance"},{"category":"section","location":"#JUCLCHEM","page":"Home","text":"Welcome to the JUCLCHEM documentation.","title":"JUCLCHEM"}]
